SELECT s.subject_id, s.hadm_id, s.stay_id, s.first_careunit, s.last_careunit, s.intime, s.outtime, s.los, p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.icd_code, d.icd_version, i.itemid, i.value, i.valueuom, i.seq_num, poe.poe_id, poe.poe_seq, poe.order_provider_id, poe.order_status, lag(i.value) OVER (PARTITION BY s.subject_id ORDER BY i.itemid) AS previous_value, lead(i.value) OVER (PARTITION BY s.subject_id ORDER BY i.itemid) AS next_value, (i.value - lag(i.value) OVER (PARTITION BY s.subject_id ORDER BY i.itemid)) / NULLIF(lag(i.value) OVER (PARTITION BY s.subject_id ORDER BY i.itemid), 0) AS percentage_change FROM icustays s JOIN patients p ON p.subject_id = s.subject_id JOIN diagnoses_icd d ON d.subject_id = p.subject_id AND d.hadm_id = s.hadm_id JOIN procedureevents i ON i.subject_id = p.subject_id AND i.hadm_id = s.hadm_id AND i.starttime BETWEEN s.intime AND s.outtime JOIN poe ON poe.poe_id = i.order_provider_id AND poe.order_status = 'completed' WHERE p.gender = 'F' AND p.anchor_age BETWEEN 83 AND 93 AND d.icd_code = '440.0' AND i.itemid = 170277 AND i.valueuom = 'score' AND i.seq_num = 1 AND s.intime <= '2020-01-01' AND s.outtime >= '2020-12-31' AND s.los <= 72;